import { FormControl } from "@chakra-ui/form-control";
import { Input } from "@chakra-ui/input";
import { Box, Text } from "@chakra-ui/layout";
import "./styles.css";
import {
  IconButton,
  Spinner,
  useToast,
  Tooltip,
} from "@chakra-ui/react";
import { getSender, getSenderFull } from "../config/ChatLogics";
import { useEffect, useState } from "react";
import axios from "axios";
import { ArrowBackIcon } from "@chakra-ui/icons";
import { FaVideo } from "react-icons/fa"; // ✅ KEEP THIS
import ProfileModal from "./miscellaneous/ProfileModal";
import ScrollableChat from "./ScrollableChat";
import Lottie from "react-lottie";
import animationData from "../animations/typing.json";

import io from "socket.io-client";
import UpdateGroupChatModal from "./miscellaneous/UpdateGroupChatModal";
import { ChatState } from "../Context/ChatProvider";

const ENDPOINT = "http://localhost:5000";
var socket, selectedChatCompare;

const SingleChat = ({ fetchAgain, setFetchAgain }) => {
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(false);
  const [newMessage, setNewMessage] = useState("");
  const [socketConnected, setSocketConnected] = useState(false);
  const [typing, setTyping] = useState(false);
  const [istyping, setIsTyping] = useState(false);
  const [meetingActive, setMeetingActive] = useState(false); // 🟢

  const toast = useToast();

  const defaultOptions = {
    loop: true,
    autoplay: true,
    animationData: animationData,
    rendererSettings: {
      preserveAspectRatio: "xMidYMid slice",
    },
  };

  const {
    selectedChat,
    setSelectedChat,
    user,
    notification,
    setNotification,
  } = ChatState();

  // 🎥 Meet
  const createMeeting = async () => {
    if (!selectedChat) return;

    const url = `https://meet.jit.si/${selectedChat._id}`;
    window.open(url, "_blank");
    setMeetingActive(true);

    try {
      await axios.post(
        "/api/message",
        {
          content: `📢 Meeting started! Join here 👉 ${url}`,
          chatId: selectedChat._id,
        },
        {
          headers: { Authorization: `Bearer ${user.token}` },
        }
      );

      setFetchAgain(!fetchAgain);
    } catch (err) {
      console.log("Error sending meeting link");
    }
  };

  const fetchMessages = async () => {
    if (!selectedChat) return;

    try {
      setLoading(true);

      const { data } = await axios.get(
        `/api/message/${selectedChat._id}`,
        {
          headers: { Authorization: `Bearer ${user.token}` },
        }
      );

      setMessages(data);
      setLoading(false);

      socket.emit("join chat", selectedChat._id);
    } catch (error) {
      toast({
        title: "Error Occured!",
        description: "Failed to Load Messages",
        status: "error",
        duration: 5000,
        isClosable: true,
      });
    }
  };

  const sendMessage = async (event) => {
    if (event.key === "Enter" && newMessage) {
      socket.emit("stop typing", selectedChat._id);

      try {
        const { data } = await axios.post(
          "/api/message",
          {
            content: newMessage,
            chatId: selectedChat._id,
          },
          {
            headers: {
              "Content-type": "application/json",
              Authorization: `Bearer ${user.token}`,
            },
          }
        );

        setNewMessage("");
        socket.emit("new message", data);
        setMessages([...messages, data]);
      } catch {
        toast({
          title: "Error sending message",
          status: "error",
        });
      }
    }
  };

  useEffect(() => {
    socket = io(ENDPOINT);
    socket.emit("setup", user);

    socket.on("connected", () => setSocketConnected(true));
    socket.on("typing", () => setIsTyping(true));
    socket.on("stop typing", () => setIsTyping(false)); // ✅ FIXED
  }, []);

  useEffect(() => {
    fetchMessages();
    selectedChatCompare = selectedChat;
  }, [selectedChat]);

  useEffect(() => {
    socket.on("message recieved", (msg) => {
      if (
        !selectedChatCompare ||
        selectedChatCompare._id !== msg.chat._id
      ) {
        if (!notification.includes(msg)) {
          setNotification([msg, ...notification]);
          setFetchAgain(!fetchAgain);
        }
      } else {
        setMessages([...messages, msg]);
      }
    });
  }, [messages]);

  const typingHandler = (e) => {
    setNewMessage(e.target.value);

    if (!socketConnected) return;

    if (!typing) {
      setTyping(true);
      socket.emit("typing", selectedChat._id);
    }

    setTimeout(() => {
      if (typing) {
        socket.emit("stop typing", selectedChat._id);
        setTyping(false);
      }
    }, 3000);
  };

  return (
    <>
      {selectedChat ? (
        <>
          {/* HEADER */}
          <Box
            display="flex"
            justifyContent="space-between"
            alignItems="center"
            w="100%"
            pb={3}
            px={2}
          >
            <Box display="flex" alignItems="center" gap="10px">
              <IconButton
                d={{ base: "flex", md: "none" }}
                icon={<ArrowBackIcon />}
                onClick={() => setSelectedChat("")}
              />

              <Text fontSize="28px">
                {selectedChat.isGroupChat
                  ? selectedChat.chatName
                  : getSender(user, selectedChat.users)}
              </Text>
            </Box>

            {/* RIGHT */}
            <Box display="flex" alignItems="center" gap="10px">
              {!selectedChat.isGroupChat && (
                <ProfileModal
                  user={getSenderFull(user, selectedChat.users)}
                />
              )}

              {selectedChat.isGroupChat && (
                <UpdateGroupChatModal
                  fetchMessages={fetchMessages}
                  fetchAgain={fetchAgain}
                  setFetchAgain={setFetchAgain}
                />
              )}

              <Tooltip label="Start Meeting">
                <Box position="relative">
                  <IconButton
                    icon={<FaVideo />}
                    onClick={createMeeting}
                    bg="blue.500"
                    color="white"
                  />

                  {meetingActive && (
                    <Box
                      position="absolute"
                      top="0"
                      right="0"
                      w="8px"
                      h="8px"
                      bg="green.400"
                      borderRadius="full"
                    />
                  )}
                </Box>
              </Tooltip>
            </Box>
          </Box>

          {/* CHAT BODY */}
          <Box flex="1" bg="#E8E8E8" p={3} borderRadius="lg">
            {loading ? (
              <Spinner />
            ) : (
              <ScrollableChat messages={messages} />
            )}

            <FormControl onKeyDown={sendMessage} mt={3}>
              <Input
                placeholder="Enter message..."
                value={newMessage}
                onChange={typingHandler}
              />
            </FormControl>
          </Box>
        </>
      ) : (
        <Text>Select a chat to start</Text>
      )}
    </>
  );
};

export default SingleChat;
